"""Cryptographic utilities for ABDM APIs.Includes:- Retrieving the ABDM public certificate.- RSA encryption utilities."""import base64import uuidimport requestsfrom cryptography.hazmat.primitives import hashes, serializationfrom cryptography.hazmat.primitives.asymmetric import paddingfrom config import ABHA_BASE_URLfrom utils import generate_request_id, generate_timestampdef get_public_certificate(token):    """    Retrieve the ABDM public certificate.    Args:        token (str): Gateway access token.    Returns:        cryptography.hazmat.primitives.asymmetric.rsa.RSAPublicKey:            Loaded RSA public key.    Raises:        requests.HTTPError: If the request fails.    """    headers = {        "Authorization": f"Bearer {token}",        "REQUEST-ID": generate_request_id(),        "TIMESTAMP": generate_timestamp(),    }    response = requests.get(        url=f"{ABHA_BASE_URL}/profile/public/certificate",        headers=headers,    )    response.raise_for_status()    public_key_str = response.json().get("publicKey").strip()    pem = (        "-----BEGIN PUBLIC KEY-----\n"        f"{public_key_str}\n"        "-----END PUBLIC KEY-----\n"    )    public_key = serialization.load_pem_public_key(        pem.encode("ascii")    )    return public_keydef encrypt_value(value, public_key):    """    Encrypt a value using RSA-OAEP with SHA-1 and return a Base64-encoded string.    Args:        value: The value to encrypt (string, int, float, etc.).        public_key: Loaded RSA public key object.    Returns:        str: Base64-encoded encrypted string.    """    # Convert any input to a string.    value = str(value)    ciphertext = public_key.encrypt(        value.encode("utf-8"),        padding.OAEP(            mgf=padding.MGF1(algorithm=hashes.SHA1()),            algorithm=hashes.SHA1(),            label=None,        ),    )    return base64.b64encode(ciphertext).decode("utf-8")